import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                result[key] = pkg.get('resolvedVersion', '')
    return result

b = extract(baseline)
a = extract(after)

print('=== CHANGES ===')
changes = False
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key, 'MISSING')
    av = a.get(key, 'MISSING')
    if bv != av:
        changes = True
        print(f'{key[0]}|{key[1]}|{key[2]}|{bv} -> {av}')

if not changes:
    print('None')

print()
print('=== UNCHANGED ===')
for key in sorted(b.keys()):
    if b.get(key) == a.get(key):
        print(f'{key[0]}|{key[1]}|{key[2]}|{b[key]}')
"", "description": "Compare baseline vs after packages", "initial_wait": 30}

